//go:build desktop

package desktop

import (
	"context"
	_ "embed"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"

	"github.com/devenjarvis/lathe/internal/agents"
	"github.com/devenjarvis/lathe/internal/config"
	"github.com/devenjarvis/lathe/internal/serve"
	"github.com/wailsapp/wails/v3/pkg/application"
	"github.com/wailsapp/wails/v3/pkg/events"
)

// appIcon is the 1024x1024 app mark (generated by appicon_gen.go). It is the
// Linux window icon and the about-box icon; the release build turns the same
// file into the macOS .icns and the Windows .ico.
//
//go:generate go run appicon_gen.go
//go:embed appicon.png
var appIcon []byte

// Window sizes. The main window fits the reader's 68ch measure with the
// docked agent panel (which docks at >= 1100px); the pop-out is a narrow
// panel-shaped window.
const (
	mainWidth, mainHeight       = 1280, 860
	mainMinWidth, mainMinHeight = 640, 480
	popWidth, popHeight         = 480, 820
	popMinWidth, popMinHeight   = 360, 420
	// The Settings window: wide enough for the five tabs in one row.
	settingsWidth, settingsHeight       = 760, 720
	settingsMinWidth, settingsMinHeight = 520, 420
)

// paper is the design system's light --bg (#FFFBF0), shown before the first
// paint so the window doesn't flash white.
var paper = application.NewRGB(0xFF, 0xFB, 0xF0)

// Available reports whether this binary was built with the desktop app. It
// was.
func Available() bool { return true }

// Run opens the desktop app and blocks until it quits (the window closes, the
// user quits from the menu, or ctx ends or SIGINT/SIGTERM arrives). If another
// Lathe app is already running, it focuses that one's window and exits this
// process instead (Wails' single-instance lock does that inside
// application.New, which is why nothing with cleanup is started before it).
func Run(ctx context.Context, opts Options) error {
	detachConsole()

	logw := opts.Log
	if logw == nil {
		logw = os.Stderr
	}
	logf := func(format string, args ...any) {
		_, _ = fmt.Fprintf(logw, "lathe: "+format+"\n", args...)
	}

	// The handler is installed after application.New: a second instance
	// exits inside New, and must not have started an agent or written
	// serve.json first.
	var assets lateHandler
	notes := newNotificationService(logf)
	sh := &shell{logf: logf}

	var single *application.SingleInstanceOptions
	if ok, why := singleInstanceUsable(); ok {
		single = &application.SingleInstanceOptions{
			UniqueID: BundleID,
			OnSecondInstanceLaunch: func(application.SecondInstanceData) {
				sh.focusMain()
			},
		}
	} else {
		logf("a second launch will open a second window: %s", why)
	}

	var cleanup func()
	app := application.New(application.Options{
		Name:        AppName,
		Description: "Hands-on technical tutorials, with your coding agent alongside.",
		Icon:        appIcon,
		Assets:      application.AssetOptions{Handler: &assets},
		Services:    []application.Service{application.NewService(notes)},
		// Run handles SIGINT/SIGTERM itself so it can quit through the app
		// and still run its cleanup.
		DisableDefaultSignalHandler: true,
		SingleInstance:              single,
		Mac: application.MacOptions{
			ApplicationShouldTerminateAfterLastWindowClosed: true,
		},
		Linux: application.LinuxOptions{
			ApplicationID: BundleID,
			ProgramName:   "lathe",
		},
		// On macOS, quitting terminates the process from inside the run
		// loop, so Run below never returns there: cleanup must run here.
		OnShutdown: func() {
			if cleanup != nil {
				cleanup()
			}
		},
	})
	sh.app = app

	if opts.PrepareEnv != nil {
		if err := opts.PrepareEnv(ctx); err != nil {
			logf("could not load your shell environment (the agent may not be found on PATH): %v", err)
		}
	}

	dir, err := config.TutorialsDir()
	if err != nil {
		return err
	}
	srv := serve.NewServer(dir)
	agentCmd := opts.Agent
	if agentCmd == "" {
		if a, ok := agents.ByID(config.Agent()); ok {
			agentCmd = a.Command
		}
	}
	if agentCmd != "" {
		srv.SetAgent(agentCmd)
	}
	sh.notes = newNotifier(notes, logf)
	srv.SetNative(sh)
	assets.set(followRedirects(srv.Handler()))

	cli, err := startBridge(srv.Handler(), logf)
	if err != nil {
		srv.Close()
		return fmt.Errorf("listen for the CLI: %w", err)
	}

	var cleanOnce sync.Once
	cleanup = func() {
		cleanOnce.Do(func() {
			cli.close()
			sh.notes.close()
			srv.Close()
		})
	}
	defer cleanup()

	mainWin := app.Window.NewWithOptions(application.WebviewWindowOptions{
		Name:             "main",
		Title:            AppName,
		URL:              "/",
		Width:            mainWidth,
		Height:           mainHeight,
		MinWidth:         mainMinWidth,
		MinHeight:        mainMinHeight,
		BackgroundColour: paper,
		InitialPosition:  application.WindowCentered,
		Linux:            application.LinuxWindow{Icon: appIcon},
	})
	sh.setMain(mainWin)
	// Closing the reader quits the app, pop-outs included: they are views of
	// it, not windows of their own.
	mainWin.OnWindowEvent(events.Common.WindowClosing, func(*application.WindowEvent) {
		go app.Quit()
	})

	sigCtx, stop := signal.NotifyContext(ctx, os.Interrupt, syscall.SIGTERM)
	defer stop()
	ran := make(chan struct{})
	defer close(ran)
	app.Event.OnApplicationEvent(events.Common.ApplicationStarted, func(*application.ApplicationEvent) {
		go func() {
			select {
			case <-sigCtx.Done():
				app.Quit()
			case <-ran:
			}
		}()
	})

	return app.Run()
}

// lateHandler lets application.New take the asset handler before the server
// exists (see Run).
type lateHandler struct{ h atomic.Pointer[http.Handler] }

func (l *lateHandler) set(h http.Handler) { l.h.Store(&h) }

func (l *lateHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	h := l.h.Load()
	if h == nil {
		http.Error(w, "Lathe is starting", http.StatusServiceUnavailable)
		return
	}
	(*h).ServeHTTP(w, r)
}
